#include <stdint.h>

#ifndef _WORD_UNION_H
#define _WORD_UNION_H
/**
 * Union to specify parts / manifestations of a 16 bit Word without casts and shifts.
 * It also supports the compiler generating small code.
 * Usage: WordUnion tWord;
 *        tWord.UByte.HighByte = 0x12;
 */
union WordUnion {
    struct {
        uint8_t LowByte;
        uint8_t HighByte;
    } UByte;
    struct {
        int8_t LowByte;
        int8_t HighByte;
    } Byte;
    uint8_t UBytes[2]; // UBytes[0] is LowByte
    int8_t Bytes[2];
    uint16_t UWord;
    int16_t Word;
    uint8_t *BytePointer;
};
#endif // _WORD_UNION_H

#ifndef _LONG_UNION_H
#define _LONG_UNION_H
/**
 * Union to specify parts / manifestations of a 32 bit Long without casts and shifts.
 * It also supports the compiler generating small code.
 */
union LongUnion {
    struct {
        uint8_t LowByte;
        uint8_t MidLowByte;
        uint8_t MidHighByte;
        uint8_t HighByte;
    } UByte;
    struct {
        int8_t LowByte;
        int8_t MidLowByte;
        int8_t MidHighByte;
        int8_t HighByte;
    } Byte;
    /* Does not work for STM32
    struct {
        uint8_t LowByte;
        uint16_t MidWord;
        uint8_t HighByte;
    } UByteWord;
    */
    struct {
        uint16_t LowWord;
        uint16_t HighWord;
    } UWord;
    struct {
        int16_t LowWord;
        int16_t HighWord;
    } Word;
    struct {
        WordUnion LowWord;
        WordUnion HighWord;
    } TwoWordUnions;
    uint8_t UBytes[4]; // seems to have the same code size as using struct UByte
    int8_t Bytes[4]; // Bytes[0] is LowByte
    uint16_t UWords[2];
    int16_t Words[2];
    uint32_t ULong;
    int32_t Long;
    float Float;
};
#endif // _LONG_UNION_H

#ifndef _LONG_LONG_UNION_H
#define _LONG_LONG_UNION_H
/**
 * Union to specify parts / manifestations of a 64 bit LongLong without casts and shifts.
 * It also supports the compiler generating small code.
 */
union LongLongUnion {
    struct {
        uint16_t LowWord;
        uint16_t MidLowWord;
        uint16_t MidHighWord;
        uint16_t HighWord;
    } UWord;
    struct {
