void timerConfigForSend(uint16_t aFrequencyKHz) {
    timerDisableReceiveInterrupt();

#  if (((F_CPU / 1000) / 38) < 256)
    const uint16_t tPWMWrapValue = (F_CPU / 1000) / (aFrequencyKHz); // 421 @16 MHz, 26 @1 MHz and 38 kHz
